{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C60"],
      "claim": "Urapidil, a close methoxyphenylpiperazine analogue, had 78% absolute oral bioavailability in healthy volunteers after a 30 mg oral solution; this high-F phenotype transfers strongly to the query's shared piperazine/methoxyphenyl core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Metoprolol, an aryloxypropanolamine sharing the OCH2CH(OH)CH2-N motif, had 55 ± 7% systemic availability after repeated 50 mg oral dosing in healthy subjects, supporting adequate oral bioavailability for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Pamatolol, another aryloxypropanolamine, showed 64.9–103.5% absolute oral bioavailability in healthy male subjects, indicating minimal first-pass loss for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Encainide, a methoxyphenyl amide with a basic amine, had 32 ± 7% absolute oral bioavailability in normal subjects, remaining above the 20% threshold despite first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C66"],
      "claim": "Bosentan, containing a 2-methoxyphenoxy ether, had approximately 50% absolute oral bioavailability in healthy volunteers, supporting adequate absorption for the query's methoxyphenoxy substructure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C63"],
      "claim": "Propranolol, an aryloxypropanolamine, had 18.9 ± 3.8% absolute oral bioavailability after a 20 mg oral dose, a below-threshold example; however, its naphthalene and secondary-amine structure and extensive first-pass metabolism are less transferable to the more polar piperazine-acetamide query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is most closely related to high-bioavailability aryloxypropanolamine and methoxyphenylpiperazine drugs such as urapidil, metoprolol, pamatolol, and bosentan, with absolute F values mostly 50–100%. The only below-threshold analogue, propranolol, is structurally less transferable. Therefore F ≥ 20% is well supported.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement exists for the query molecule.",
    "First-pass metabolism and transporter effects specific to the piperazine-acetamide anilide moiety are not directly characterized.",
    "The propranolol low-F example indicates hepatic first-pass could lower F, but structural differences limit its transferability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

